`timescale 1ns/1ps

module counter_tb;
    // Inputs (reg) and Outputs (wire)
    reg clk;
    reg rst;
    wire [3:0] out;

    // Instantiate the Design Under Test (DUT)
    counter uut (
        .clk(clk),
        .rst(rst),
        .out(out)
    );

    // 1. Clock Generation: toggle every 5 time units (10ns period)
    always #5 clk = ~clk;

    // 2. Stimulus
    initial begin
        // Initialize signals
        clk = 0;
        rst = 0;

        // Apply Reset
        #2 rst = 1;
        #10 rst = 0;

        // Let the counter run for a while
        #100;

        // Finish the simulation
        $finish;
    end

    // 3. Icarus Verilog specific waveform dumping
    initial begin
        $dumpfile("counter_wave.vcd"); // Name of the waveform file
        $dumpvars(0, counter_tb);      // Record all signals in the testbench
    end

endmodule

