module tb_counter_tb;
  logic clk = 0;
  logic reset_n = 0;
  logic done;

  always #5 clk = ~clk;

  // Connect this instance to the real design ports before simulating.
  // counter_tb dut (.clk(clk), .reset_n(reset_n), .done(done));

  task build_phase();
    // Allocate scoreboards, monitors, or interfaces here in a fuller UVM environment.
  endtask

  task run_phase();
    reset_n = 0;
    repeat (4) @(posedge clk);
    reset_n = 1;
