`timescale 1ns/1ps
module tb_jk_flip_flop;

    // Signal declarations
    reg  clk;
    reg  rst_n;
    reg  j;
    reg  k;
    wire q;
    wire q_bar;

    // Instantiate the Device Under Test (DUT)
    jk_flip_flop dut (
        .clk   (clk),
        .rst_n (rst_n),
        .j     (j),
        .k     (k),
        .q     (q),
        .q_bar (q_bar)
    );

    // Clock generator (50MHz / 20ns period)
    always begin
        clk = 1'b0;
        #10;
        clk = 1'b1;
        #10;
    end

    // Stimulus process
    initial begin
        // Required for Icarus Verilog to generate waveform files
        $dumpfile("jk_ff_wave.vcd");
        $dumpvars(0, tb_jk_flip_flop);

        // Initialize inputs
        j = 1'b0;
        k = 1'b0;
        rst_n = 1'b0; // Apply reset
        #25;          // Wait for a non-edge time

        rst_n = 1'b1; // Release reset
        #5;

        // Test Case 1: Hold State (J=0, K=0)
        j = 1'b0; k = 1'b0; #20;

        // Test Case 2: Set State (J=1, K=0)
        j = 1'b1; k = 1'b0; #20;

        // Test Case 3: Hold State (J=0, K=0)
        j = 1'b0; k = 1'b0; #20;

        // Test Case 4: Reset State (J=0, K=1)
        j = 1'b0; k = 1'b1; #20;

        // Test Case 5: Toggle State (J=1, K=1)
        j = 1'b1; k = 1'b1; #20;

        // Test Case 6: Toggle State continuous (J=1, K=1)
        #20;

        // Test Case 7: Asynchronous Reset during operation
        #5;
        rst_n = 1'b0; 
        #15;

        // Finish simulation
        $display("Simulation completed successfully.");
        $finish;
    end

    // Monitor changes in the console terminal
    initial begin
        $monitor("Time=%0d ns | Reset=%b | J=%b K=%b | Q=%b Q_bar=%b", 
                 $time, rst_n, j, k, q, q_bar);
    end

endmodule

