//-----------------------------------------------------------------------------
// Title         : clkdiv - clock divider
//-----------------------------------------------------------------------------

module clkdiv(
    input  logic clk,
    input  logic reset,
    output logic sclk
);
    parameter DIVFREQ = 1000;          // desired frequency in Hz
    parameter DIVBITS = 26;            // enough bits to divide 100 MHz down to 1 Hz
    parameter CLKFREQ = 100_000_000;
    parameter DIVAMT  = (CLKFREQ / DIVFREQ) / 2;

    logic [DIVBITS-1:0] q;

    always_ff @(posedge clk) begin
        if (reset) begin
            q    <= '0;
            sclk <= 1'b0;
        end else if (q == DIVAMT - 1) begin
            q    <= '0;
            sclk <= ~sclk;
        end else begin
            q <= q + {{(DIVBITS-1){1'b0}}, 1'b1};
        end
    end
endmodule

`timescale 1ns / 1ps

module count_3bit(
    input  logic clk, rst, en,
    output logic [2:0] q
);
    always_ff @(posedge clk) begin
        if (rst)      q <= 3'd0;
        else if (en)  q <= q + 3'd1;
        else          q <= 3'd0;
    end
endmodule

`timescale 1ns / 1ps
//-----------------------------------------------------------------------------
// Title         : counter_bcd - simple 4-bit BCD counter
//-----------------------------------------------------------------------------

module counter_bcd(
    input  logic clk, rst, enb,
    output logic [3:0] q,
    output logic carry
);
    assign carry = (q == 4'd9) && enb;

    always_ff @(posedge clk) begin
        if (rst || carry) q <= 4'd0;
        else if (enb)     q <= q + 4'd1;
    end
endmodule

`timescale 1ns / 1ps

module delay_counter(
    input  logic rst, clk,
    output logic [12:0] W
);
    always_ff @(posedge clk) begin
        if (rst) W <= '0;
        else     W <= W + 13'd1;
    end
endmodule

`timescale 1ns / 1ps

module delay_counter5(
    input  logic rst, clk, start_wait5,
    output logic wait5_done
