`timescale 1ns / 1ps

module rgb_pwm(
    input  logic clk, rst,
    input  logic [2:0] color_r, color_g, color_b,
    output logic rgb_r, rgb_g, rgb_b
);
    logic [3:0] rbgcount;

    always_ff @(posedge clk) begin
        if (rst) rbgcount <= '0;
        else     rbgcount <= rbgcount + 4'd1;
    end

    always_comb begin
        if (rbgcount < color_r) rgb_r = 1'b1; else rgb_r = 1'b0;
        if (rbgcount < color_g) rgb_g = 1'b1; else rgb_g = 1'b0;
        if (rbgcount < color_b) rgb_b = 1'b1; else rgb_b = 1'b0;
    end
endmodule

`timescale 1ns / 1ps

module random_wait(
    input  logic clk, rst, start_rwait,
    output logic wait_done
);
    logic [2:0] random_num, q, qinc;
    logic [12:0] w, W;
    logic commonstart;

    assign commonstart = start_rwait;

    delay_counter WAIT5(
        .clk(clk), .rst(rst || !commonstart || wait_done), .W(W)
    );

    count_3bit COUNT3(
        .clk(clk), .rst(rst), .q(random_num), .en(start_rwait)
    );

    incrementor INC(
        .q(q), .qinc(qinc)
    );

    randomnum_reg RANDOM(
        .rst(rst), .clk(clk), .d(random_num), .q(q), .en(commonstart)
    );

    multiplier MULTIPLY(
        .qinc(qinc), .w(w)
    );

    always_comb begin
        if (commonstart && (w == W)) wait_done = 1'b1;
        else                        wait_done = 1'b0;
    end
endmodule

`timescale 1ns / 1ps

module reaction_FSM(
    input  logic start, enter, rwait_done, wait5_done, time_late, rst, clk,
    output logic [2:0] color_r, color_g, color_b,
    output logic time_clr, time_en, start_wait5, start_rwait, rs_en
);
    typedef enum logic [2:0] {
        IDLE    = 3'b000,
        RWAIT   = 3'b001,
        WHITE   = 3'b010,
        RED     = 3'b011,
        YELLOW  = 3'b100,
        GREEN   = 3'b101,
        DISPLAY = 3'b110
    } states_t;

    states_t state, next;

    always_ff @(posedge clk) begin
        if (rst) state <= GREEN;
        else     state <= next;
    end

    always_comb begin
        next = GREEN;
        unique case (state)
            IDLE: begin
                color_r = 3'd0; color_g = 3'd2; color_b = 3'd0;
                time_clr = 1'b1; start_rwait = 1'b0; start_wait5 = 1'b0; rs_en = 1'b0; time_en = 1'b0;
                if (start) next = RWAIT;
                else       next = IDLE;
            end

            GREEN: begin
                color_r = 3'd0; color_g = 3'd2; color_b = 3'd0;
                time_clr = 1'b1; start_rwait = 1'b0; time_en = 1'b0; start_wait5 = 1'b0; rs_en = 1'b0;
                if (start) next = RWAIT;
                else       next = GREEN;
            end

            RWAIT: begin
                color_r = 3'd0; color_g = 3'd0; color_b = 3'd0;
                time_clr = 1'b1; start_rwait = 1'b1; time_en = 1'b0; start_wait5 = 1'b0; rs_en = 1'b0;
                if (rwait_done)              next = WHITE;
                else if (enter & ~rwait_done) next = RED;
                else                         next = RWAIT;
            end

            RED: begin
                color_r = 3'd7; color_g = 3'd0; color_b = 3'd0;
                start_wait5 = 1'b1; time_clr = 1'b1; start_rwait = 1'b0; time_en = 1'b0; rs_en = 1'b0;
                if (wait5_done) next = IDLE;
                else            next = RED;
            end

            WHITE: begin
                color_r = 3'd4; color_g = 3'd2; color_b = 3'd3;
                start_rwait = 1'b0; rs_en = 1'b0; time_en = 1'b1; start_wait5 = 1'b0; time_clr = 1'b0;
                if (time_late)               next = YELLOW;
                else if (enter & ~time_late) next = DISPLAY;
                else                         next = WHITE;
            end

            DISPLAY: begin
                color_r = 3'd0; color_g = 3'd2; color_b = 3'd0;
                start_rwait = 1'b0; rs_en = 1'b1; time_clr = 1'b0; time_en = 1'b0; start_wait5 = 1'b0;
                if (start) next = IDLE;
                else       next = DISPLAY;
            end

            YELLOW: begin
                color_r = 3'd7; color_g = 3'd2; color_b = 3'd0;
                time_clr = 1'b1; start_rwait = 1'b0; time_en = 1'b0; start_wait5 = 1'b1; rs_en = 1'b0;
                if (wait5_done) next = IDLE;
                else            next = YELLOW;
            end

            default: begin
                color_r = 3'd0; color_g = 3'd0; color_b = 3'd0;
                time_clr = 1'b1; start_rwait = 1'b0; start_wait5 = 1'b0; rs_en = 1'b0; time_en = 1'b0;
                next = GREEN;
            end
        endcase
    end
endmodule

`timescale 1ns / 1ps

module sevenseg_control(
    input  logic clk, rst,
    input  logic en,
    input  logic [3:0] d0, d1, d2, d3,
    output logic dot,
    output logic [7:0] y_n,
    output logic [6:0] segs_n
